//! Repository for SalaryComponent entities
//!
//! Originally generated by metaphor-schema; now **user-owned** — this exact path is declared under
//! `user_owned` in `metaphor.codegen.yaml`, so the generator skips it wholesale. The custom methods
//! below hold the hand-written SalaryComponent SQL (4-layer rule: services orchestrate, repos hold SQL).
//!
//! Thin newtype over `backbone_orm::GenericCrudRepository<SalaryComponent, backbone_orm::SoftDelete>`.
//! All standard CRUD methods are available via `Deref`.

use anyhow::Result;
use chrono::NaiveDate;
use rust_decimal::Decimal;
use sqlx::{PgPool, Row};
use uuid::Uuid;

// The multi-row read twin rides the `org_scope` module: request-dedicated connection when
// the composer bound one, plain pool otherwise, no scope invented. This module sets no
// scope of its own (ADR-0029), so nothing reaches for a legacy company bind.
use backbone_orm::org_scope::fetch_all_rows_scoped;

use crate::domain::entity::SalaryComponent;

/// Table name for SalaryComponent entities
pub const TABLE_NAME: &str = "payroll.salary_components";

/// Repository for SalaryComponent entities.
///
/// All standard CRUD, soft-delete, pagination, and bulk methods are
/// provided automatically via `Deref` to `backbone_orm::GenericCrudRepository`.
pub struct SalaryComponentRepository(
    backbone_orm::GenericCrudRepository<SalaryComponent, backbone_orm::SoftDelete>,
);

impl std::ops::Deref for SalaryComponentRepository {
    type Target = backbone_orm::GenericCrudRepository<SalaryComponent, backbone_orm::SoftDelete>;
    fn deref(&self) -> &Self::Target { &self.0 }
}

impl SalaryComponentRepository {
    /// Create a new repository instance.
    pub fn new(pool: PgPool) -> Self {
        Self(backbone_orm::GenericCrudRepository::new(pool, TABLE_NAME))
    }
}

/// The exact row one structure component writes.
///
/// Mirrors the raw column shape rather than the `SalaryComponent` entity: `component_type` is cast at
/// the DB (`$4::component_type`), which is what lets a bad variant fail as a DB error instead of a
/// deserialize panic. `amount` is the service's already money-rounded value.
pub struct NewComponentRow<'a> {
    pub id: Uuid,
    pub structure_id: Uuid,
    pub name: &'a str,
    pub component_type: &'a str,
    pub amount: Decimal,
    pub gl_account_id: Uuid,
}

/// One structure component, as the slip builder reads it: `component_type` comes back as text so the
/// service can branch earning-vs-deduction without a domain enum in the way.
pub struct ComponentRow {
    pub name: String,
    pub component_type: String,
    pub amount: Decimal,
    pub gl_account_id: Uuid,
}

/// Hand-written SalaryComponent SQL. Lives here (not in the write service) per the module's 4-layer
/// rule: services orchestrate and own the unit of work, repositories hold the SQL.
impl SalaryComponentRepository {
    /// Insert one earning/deduction component of a structure.
    ///
    /// Takes the CALLER'S connection so the structure and all its components commit as ONE unit. The
    /// caller has already relayed the ambient org request scope onto it — don't re-bind here. The
    /// component's own org scoping rides its parent structure row (ADR-0029); the module carries no
    /// denormalized tenancy column.
    pub async fn insert_component(
        &self,
        conn: &mut sqlx::PgConnection,
        c: &NewComponentRow<'_>,
    ) -> Result<(), sqlx::Error> {
        sqlx::query(
            r#"INSERT INTO payroll.salary_components
                 (id, structure_id, name, component_type, amount, gl_account_id)
               VALUES ($1,$2,$3,$4::component_type,$5,$6)"#,
        )
        .bind(c.id).bind(c.structure_id).bind(c.name).bind(c.component_type)
        .bind(c.amount).bind(c.gl_account_id)
        .execute(conn)
        .await?;
        Ok(())
    }

    /// List a structure's components as they stand on `as_of` — the earnings and fixed deductions a
    /// slip for a period starting that day is assembled from.
    ///
    /// A component with dated versions reads the version in force on `as_of`, and is not paid
    /// before its first version or from a version that removes it; one without versions reads its
    /// row. So a run for an earlier month reads what the structure was then, and a change planned
    /// from a later date leaves this one alone.
    ///
    /// A read outside any transaction: takes the pool and runs `fetch_all_rows_scoped` so the
    /// composing service's tenancy RLS fence applies (ADR-0029). The caller relays the ambient org
    /// request scope onto its own transaction first, or runs under HTTP where the
    /// request-dedicated connection already carries it.
    pub async fn list_by_structure(
        &self,
        pool: &PgPool,
        structure_id: Uuid,
        as_of: NaiveDate,
    ) -> Result<Vec<ComponentRow>, sqlx::Error> {
        // Only what a slip is assembled from: a removed item is not paid, and a statutory item
        // (BPJS, PPh 21) only marks that the rule applies — its amount is the statutory line the
        // run computes from gross, so reading it here would charge it twice.
        let rows = fetch_all_rows_scoped(
            pool,
            sqlx::query(
                r#"SELECT COALESCE(v.name, c.name) AS name,
                          COALESCE(v.component_type, c.component_type)::text AS ct,
                          COALESCE(v.amount, c.amount) AS amount,
                          COALESCE(v.gl_account_id, c.gl_account_id) AS gl_account_id
                     FROM payroll.salary_components c
                     LEFT JOIN LATERAL (
                          SELECT x.name, x.component_type, x.amount, x.gl_account_id, x.is_statutory, x.removed
                            FROM payroll.salary_component_versions x
                           WHERE x.component_id = c.id AND x.effective_from <= $2
                             AND (x.metadata->>'deleted_at') IS NULL
                           ORDER BY x.effective_from DESC
                           LIMIT 1) v ON true
                    WHERE c.structure_id = $1
                      AND CASE WHEN EXISTS (SELECT 1 FROM payroll.salary_component_versions y
                                             WHERE y.component_id = c.id AND (y.metadata->>'deleted_at') IS NULL)
                               THEN v.name IS NOT NULL AND NOT v.removed AND NOT v.is_statutory
                               ELSE NOT c.is_statutory AND (c.metadata->>'deleted_at') IS NULL
                          END"#)
                .bind(structure_id)
                .bind(as_of),
        )
        .await?;
        Ok(rows.iter().map(|r| ComponentRow {
            name: r.get("name"), component_type: r.get("ct"), amount: r.get("amount"),
            gl_account_id: r.get("gl_account_id"),
        }).collect())
    }
}

backbone_core::impl_crud_repository!(SalaryComponentRepository, SalaryComponent, soft_delete);
